                key = unchecked((long)(0UL + index));
            }
            return key;
        }

        internal void __WriteFields(ref GesBitWriter writer, string[] paths, int at)
        {
            if (Id < 0L || unchecked((ulong)Id - 0UL) > 65535UL) throw new GesWireException(GesWireException.OutOfRange, paths[at + 0]);
            writer.Write(unchecked((ulong)Id - 0UL), 16);
            Pose.__WriteFields(ref writer, paths, at + 2);
            if (Health < 0L || unchecked((ulong)Health - 0UL) > 100UL) throw new GesWireException(GesWireException.OutOfRange, paths[at + 5]);
            writer.Write(unchecked((ulong)Health - 0UL), 7);
            writer.Write(Firing ? 1UL : 0UL, 1);
            if (HasTarget)
            {
                writer.Write(1, 1);
                if (Target < 0L || unchecked((ulong)Target - 0UL) > 65535UL) throw new GesWireException(GesWireException.OutOfRange, paths[at + 7]);
                writer.Write(unchecked((ulong)Target - 0UL), 16);
            }
            else writer.Write(0, 1);
            {
                var text = new ReadOnlySpan<byte>(__Name, 0, __NameLength);
                if (text.Length > 12) throw new GesWireException(GesWireException.TooLong, paths[at + 8]);
                if (!GesWireRules.IsValidUtf8(text)) throw new GesWireException(GesWireException.InvalidText, paths[at + 8]);
                writer.Write((ulong)text.Length, 4);
                writer.WriteBytes(text);
            }
        }

        internal void __ReadFields(ref GesBitReader reader, string[] paths, int at)
        {
            {
                var index = reader.Read(16, paths[at + 0]);
                Id = unchecked((long)(0UL + index));
            }
            Pose.__ReadFields(ref reader, paths, at + 2);
            {
                var index = reader.Read(7, paths[at + 5]);
                if (index > 100UL) throw new GesWireException(GesWireException.InvalidIndex, paths[at + 5]);
                Health = unchecked((long)(0UL + index));
            }
            Firing = reader.Read(1, paths[at + 6]) != 0;
            HasTarget = reader.Read(1, paths[at + 7]) != 0;
            if (HasTarget)
            {
                {
                    var index = reader.Read(16, paths[at + 7]);
                    Target = unchecked((long)(0UL + index));
                }
            }
            else Target = default;
            {
                var count = (int)reader.Read(4, paths[at + 8]);
                if (count > 12) throw new GesWireException(GesWireException.InvalidCount, paths[at + 8]);
                reader.Require(count * 8L, paths[at + 8]);
                if (__Name.Length < count) Array.Resize(ref __Name, Math.Max(count, Math.Min(12, __Name.Length * 2)));
                var text = new Span<byte>(__Name, 0, count);
                reader.ReadBytes(text, paths[at + 8]);
                if (!GesWireRules.IsValidUtf8(text)) throw new GesWireException(GesWireException.InvalidText, paths[at + 8]);
                __NameLength = count;
            }
        }

        internal bool __Busy;

        internal void __Mark(bool busy) => __Busy = busy;

        internal bool __Holds() => __Busy;

        internal bool __SharesList(Ship baseline)
        {
            return false;
        }

        private bool __Same8(Ship baseline, string[] paths, int at)
        {
            if (!new ReadOnlySpan<byte>(__Name, 0, __NameLength).SequenceEqual(new ReadOnlySpan<byte>(baseline.__Name, 0, baseline.__NameLength))) return false;
            return true;
        }

        private static ulong __Wire0(long value, string[] paths, int at)
        {
            if (value < 0L || unchecked((ulong)value - 0UL) > 65535UL) throw new GesWireException(GesWireException.OutOfRange, paths[at + 0]);
            return unchecked((ulong)value - 0UL);
        }

        private static ulong __Read0(ref GesBitReader reader, string[] paths, int at)
        {
            var wire = reader.Read(16, paths[at + 0]);
            return wire;
        }

        private static long __Value0(ulong wire) => unchecked((long)(0UL + wire));

        private static ulong __Wire5(long value, string[] paths, int at)
        {
            if (value < 0L || unchecked((ulong)value - 0UL) > 100UL) throw new GesWireException(GesWireException.OutOfRange, paths[at + 5]);
            return unchecked((ulong)value - 0UL);
        }

        private static ulong __Read5(ref GesBitReader reader, string[] paths, int at)
        {
            var wire = reader.Read(7, paths[at + 5]);
            if (wire > 100UL) throw new GesWireException(GesWireException.InvalidIndex, paths[at + 5]);
            return wire;
        }

        private static long __Value5(ulong wire) => unchecked((long)(0UL + wire));

        private static ulong __Wire6(bool value, string[] paths, int at)
        {
            return value ? 1UL : 0UL;
        }

        private static ulong __Read6(ref GesBitReader reader, string[] paths, int at)
        {
            var wire = reader.Read(0, paths[at + 6]);
            return wire;
        }

        private static bool __Value6(ulong wire) => wire != 0;

        private static ulong __Wire7(long value, string[] paths, int at)
        {
            if (value < 0L || unchecked((ulong)value - 0UL) > 65535UL) throw new GesWireException(GesWireException.OutOfRange, paths[at + 7]);
            return unchecked((ulong)value - 0UL);
        }

        private static ulong __Read7(ref GesBitReader reader, string[] paths, int at)
        {
            var wire = reader.Read(16, paths[at + 7]);
            return wire;
        }

        private static long __Value7(ulong wire) => unchecked((long)(0UL + wire));

        internal bool __Same(Ship other, string[] paths, int at)
        {
            if (__Wire0(Id, paths, at) != __Wire0(other.Id, paths, at)) return false;
            if (!Pose.__Same(other.Pose, paths, at + 2)) return false;
            if (__Wire5(Health, paths, at) != __Wire5(other.Health, paths, at)) return false;
            if (Firing != other.Firing) return false;
            if (HasTarget != other.HasTarget) return false;
            if (HasTarget)
            {
                if (__Wire7(Target, paths, at) != __Wire7(other.Target, paths, at)) return false;
            }
            if (!new ReadOnlySpan<byte>(__Name, 0, __NameLength).SequenceEqual(new ReadOnlySpan<byte>(other.__Name, 0, other.__NameLength))) return false;
            return true;
        }

        /// <summary>Copies the values of another record into the storage of this one, without allocating once it has grown.</summary>
        /// <param name="other">The record to copy.</param>
        public void CopyFrom(Ship other)
        {
            if (ReferenceEquals(this, other)) return;
            Id = other.Id;
            Pose = other.Pose;
            Health = other.Health;
            Firing = other.Firing;
            HasTarget = other.HasTarget;
            Target = other.Target;
            SetNameUtf8(new ReadOnlySpan<byte>(other.__Name, 0, other.__NameLength));
        }

        internal void __Quantize(string[] paths, int at)
        {
            Pose.__Quantize(paths, at + 2);
            if (HasTarget)
            {
            }
        }

        /// <summary>Gets whether another schema has the same wire values, so that it writes the same bytes.</summary>
        /// <param name="other">The other record.</param>
        /// <returns>Whether the wire values are equal.</returns>
        /// <exception cref="GesWireException">A compared value has no wire value, such as a number outside its range.</exception>
        public bool WireEquals(Ship other) => __Same(other, __paths, 0);

        /// <summary>Replaces every quantized value by the value its index decodes to, which a receiver reads.</summary>
        /// <exception cref="GesWireException">A quantized value lies outside its range.</exception>
        public void Quantize() => __Quantize(__paths, 0);

        internal ulong __KeyOrder(string[] paths, int at) => __Wire0(Id, paths, at);

        internal static ulong __ReadKeyOrder(ref GesBitReader reader, string[] paths, int at) => __Read0(ref reader, paths, at);

        /// <summary>Writes what differs from a baseline, the full record the receiver holds; <see cref="MaxByteCount"/> bytes always suffice.</summary>
        /// <param name="baseline">The baseline, another instance.</param>
        /// <param name="buffer">The buffer.</param>
        /// <returns>The number of bytes written.</returns>
        /// <exception cref="GesWireException">A value does not fit its field, the keys differ, or the buffer is too small.</exception>
        public int WriteDelta(Ship baseline, Span<byte> buffer)
        {
            var writer = new GesBitWriter(buffer);
            var paths = __paths;
            const int at = 0;
            var key = __Wire0(Id, paths, at);
            if (key != __Wire0(baseline.Id, paths, at)) throw new GesWireException(GesWireException.KeyMismatch, paths[0]);
            writer.Write(key, 16);
            __WriteDelta(baseline, ref writer, __paths, 0, true);
            return writer.Finish();
        }

        /// <summary>Writes what differs from a baseline into a new array of its exact size.</summary>
        /// <param name="baseline">The baseline, another instance.</param>
        /// <returns>The bytes.</returns>
        /// <exception cref="GesWireException">A value does not fit its field, or the keys differ.</exception>
        public byte[] ToDeltaBytes(Ship baseline)
        {
            var buffer = new byte[MaxByteCount];
            return buffer.AsSpan(0, WriteDelta(baseline, buffer)).ToArray();
        }

        /// <summary>Reads a delta against a baseline into this instance. After an error its values are unspecified.</summary>
        /// <param name="data">The delta; it may continue after it.</param>
        /// <param name="baseline">The baseline, another instance.</param>
        /// <param name="byteLimit">An optional limit on the bytes of this delta.</param>
        /// <returns>The number of bytes the delta occupies.</returns>
        /// <exception cref="GesWireException">The data is no valid delta for this baseline.</exception>
        public int ReadDelta(ReadOnlySpan<byte> data, Ship baseline, long byteLimit = long.MaxValue)
        {
            if (ReferenceEquals(this, baseline)) throw new GesWireException(GesWireException.OverlappingBuffers, "");
            #if DEBUG
            __Mark(true);
            var shared = baseline.__Holds();
            __Mark(false);
            if (shared || __SharesList(baseline)) throw new GesWireException(GesWireException.OverlappingBuffers, "");
            #endif
            var reader = new GesBitReader(data, byteLimit);
            var paths = __paths;
            const int at = 0;
            var key = __Read0(ref reader, paths, at);
            if (key != __Wire0(baseline.Id, paths, at)) throw new GesWireException(GesWireException.InvalidDelta, paths[0]);
            __ReadDelta(baseline, ref reader, __paths, 0, true);
            return reader.Finish();
        }

        internal bool __WriteDelta(Ship baseline, ref GesBitWriter writer, string[] paths, int at, bool top)
        {
            var first = writer.BitPosition;
            for (var left = top ? 5 : 6; left > 0; left -= 64) writer.Write(0, Math.Min(left, 64));
            var changed = false;
            var ordinal = 0;
            if (!top)
            {
                var set0 = false;
                {
                    var value0 = __Wire0(Id, paths, at);
                    var held0 = __Wire0(baseline.Id, paths, at);
                    if (value0 != held0)
                    {
                        writer.Write(value0, 16);
                        set0 = true;
                    }
                }
                if (set0)
                {
                    writer.SetBit(first + ordinal);
                    changed = true;
                }
                ordinal++;
            }
            {
                var set1 = false;
                {
                    var start1 = writer.BitPosition;
                    if (Pose.__WriteDelta(baseline.Pose, ref writer, paths, at + 2, false)) set1 = true;
                    else writer.Rewind(start1);
                }
                if (set1)
                {
                    writer.SetBit(first + ordinal);
                    changed = true;
                }
                ordinal++;
            }
            {
                var set5 = false;
                {
                    var value5 = __Wire5(Health, paths, at);
                    var held5 = __Wire5(baseline.Health, paths, at);
                    if (value5 != held5)
                    {
                        writer.Write(value5, 7);
                        set5 = true;
                    }
                }
                if (set5)
                {
                    writer.SetBit(first + ordinal);
                    changed = true;
                }
                ordinal++;
            }
            {
                var set6 = false;
                if (Firing != baseline.Firing) set6 = true;
                if (set6)
                {
                    writer.SetBit(first + ordinal);
                    changed = true;
                }
                ordinal++;
            }
            {
                var set7 = false;
                if (HasTarget != baseline.HasTarget)
                {
                    writer.Write(HasTarget ? 1UL : 0UL, 1);
                    if (HasTarget)
                    {
                        if (Target < 0L || unchecked((ulong)Target - 0UL) > 65535UL) throw new GesWireException(GesWireException.OutOfRange, paths[at + 7]);
                        writer.Write(unchecked((ulong)Target - 0UL), 16);
                    }
                    set7 = true;
                }
                else if (HasTarget)
                {
                    var presence7 = writer.BitPosition;
                    writer.Write(1, 1);
                    {
                        var value7 = __Wire7(Target, paths, at);
                        var held7 = __Wire7(baseline.Target, paths, at);
                        if (value7 != held7)
                        {
                            writer.Write(value7, 16);
                            set7 = true;
                        }
                    }
                    if (!set7) writer.Rewind(presence7);
                }
                if (set7)
                {
                    writer.SetBit(first + ordinal);
                    changed = true;
                }
                ordinal++;
            }
            {
                var set8 = false;
                if (!__Same8(baseline, paths, at))
                {
                    {
                        var text = new ReadOnlySpan<byte>(__Name, 0, __NameLength);
                        if (text.Length > 12) throw new GesWireException(GesWireException.TooLong, paths[at + 8]);
                        if (!GesWireRules.IsValidUtf8(text)) throw new GesWireException(GesWireException.InvalidText, paths[at + 8]);
                        writer.Write((ulong)text.Length, 4);
                        writer.WriteBytes(text);
                    }
                    set8 = true;
                }
                if (set8)
                {
                    writer.SetBit(first + ordinal);
                    changed = true;
                }
                ordinal++;
            }
            return changed;
        }

        internal bool __ReadDelta(Ship baseline, ref GesBitReader reader, string[] paths, int at, bool top)
        {
            var fieldCount = top ? 5 : 6;
            reader.Require(fieldCount, at == 0 ? "" : paths[at - 1]);
            var changeBits = reader.BitPosition;
            reader.Seek(changeBits + fieldCount);
            var changed = false;
            var ordinal = 0;
            if (!top)
            {
                var payload0 = reader.BitPosition;
                reader.Seek(changeBits + ordinal);
                var set0 = reader.Read(1, paths[at + 0]) == 1;
                reader.Seek(payload0);
                if (set0)
                {
                    {
                        var held0 = __Wire0(baseline.Id, paths, at);
                        var value0 = __Read0(ref reader, paths, at);
                        if (value0 == held0) throw new GesWireException(GesWireException.InvalidDelta, paths[at + 0]);
                        Id = __Value0(value0);
                    }
                    changed = true;
                }
                else
                {
                    Id = baseline.Id;
                }
                ordinal++;
            }
            else Id = __Value0(__Wire0(baseline.Id, paths, at));
            {
                var payload1 = reader.BitPosition;
                reader.Seek(changeBits + ordinal);
                var set1 = reader.Read(1, paths[at + 1]) == 1;
                reader.Seek(payload1);
                if (set1)
                {
                    if (!Pose.__ReadDelta(baseline.Pose, ref reader, paths, at + 2, false)) throw new GesWireException(GesWireException.InvalidDelta, paths[at + 1]);
                    changed = true;
                }
                else
                {
                    Pose = baseline.Pose;
                }
                ordinal++;
            }
            {
                var payload5 = reader.BitPosition;
                reader.Seek(changeBits + ordinal);
                var set5 = reader.Read(1, paths[at + 5]) == 1;
                reader.Seek(payload5);
                if (set5)
                {
                    {
                        var held5 = __Wire5(baseline.Health, paths, at);
                        var value5 = __Read5(ref reader, paths, at);
                        if (value5 == held5) throw new GesWireException(GesWireException.InvalidDelta, paths[at + 5]);
                        Health = __Value5(value5);
                    }
                    changed = true;
                }
                else
                {
                    Health = baseline.Health;
                }
                ordinal++;
            }
            {
                var payload6 = reader.BitPosition;
                reader.Seek(changeBits + ordinal);
                var set6 = reader.Read(1, paths[at + 6]) == 1;
                reader.Seek(payload6);
                if (set6)
                {
                    Firing = !baseline.Firing;
                    changed = true;
                }
                else
                {
                    Firing = baseline.Firing;
                }
                ordinal++;
            }
            {
                var payload7 = reader.BitPosition;
                reader.Seek(changeBits + ordinal);
                var set7 = reader.Read(1, paths[at + 7]) == 1;
                reader.Seek(payload7);
                if (set7)
                {
                    var present7 = reader.Read(1, paths[at + 7]) == 1;
                    if (!present7 && !baseline.HasTarget) throw new GesWireException(GesWireException.InvalidDelta, paths[at + 7]);
                    HasTarget = present7;
                    if (present7 && baseline.HasTarget)
                    {
                        {
                            var held7 = __Wire7(baseline.Target, paths, at);
                            var value7 = __Read7(ref reader, paths, at);
                            if (value7 == held7) throw new GesWireException(GesWireException.InvalidDelta, paths[at + 7]);
                            Target = __Value7(value7);
                        }
                    }
                    else if (present7)
                    {
                        {
                            var index = reader.Read(16, paths[at + 7]);
                            Target = unchecked((long)(0UL + index));
                        }
                    }
                    else Target = default;
                    changed = true;
                }
                else
                {
                    HasTarget = baseline.HasTarget;
                    Target = baseline.Target;
                }
                ordinal++;
            }
            {
                var payload8 = reader.BitPosition;
                reader.Seek(changeBits + ordinal);
                var set8 = reader.Read(1, paths[at + 8]) == 1;
                reader.Seek(payload8);
                if (set8)
                {
                    {
                        var count = (int)reader.Read(4, paths[at + 8]);
                        if (count > 12) throw new GesWireException(GesWireException.InvalidCount, paths[at + 8]);
                        reader.Require(count * 8L, paths[at + 8]);
                        if (__Name.Length < count) Array.Resize(ref __Name, Math.Max(count, Math.Min(12, __Name.Length * 2)));
                        var text = new Span<byte>(__Name, 0, count);
                        reader.ReadBytes(text, paths[at + 8]);
                        if (!GesWireRules.IsValidUtf8(text)) throw new GesWireException(GesWireException.InvalidText, paths[at + 8]);
                        __NameLength = count;
                    }
                    if (__Same8(baseline, paths, at)) throw new GesWireException(GesWireException.InvalidDelta, paths[at + 8]);
                    changed = true;
                }
                else
                {
                    SetNameUtf8(new ReadOnlySpan<byte>(baseline.__Name, 0, baseline.__NameLength));
                }
                ordinal++;
            }
            return changed;
        }
    }
